const staticData = $getWorkflowStaticData('global');
const sessions = staticData.knowledgeHubSessions || {};
const SESSION_TTL = 30 * 60 * 1000;

const msg = $input.first().json.message;
const chatId = msg.chat.id.toString();
const text = (msg.text || '').trim().replace(/@\w+$/, '').trim();
const now = Date.now();

// Clean expired sessions
for (const [id, s] of Object.entries(sessions)) {
  if (now - s.lastActivity > SESSION_TTL) delete sessions[id];
}

// /cancel or /reset
if (text === '/cancel' || text === '/reset') {
  delete sessions[chatId];
  staticData.knowledgeHubSessions = sessions;
  return [{ json: { action: 'cancelled', chatId, text, message: msg } }];
}

// Touch/init session
if (!sessions[chatId]) {
  sessions[chatId] = { state: 'idle', lastActivity: now };
} else {
  sessions[chatId].lastActivity = now;
}
staticData.knowledgeHubSessions = sessions;

return [{ json: { action: 'continue', chatId, text, message: msg } }];

const text = $input.first().json.text || '';
const urlMatch = text.match(/https?:\/\/[^\s]+/);
let url = urlMatch ? urlMatch[0] : null;

if (url) {
  // Strip text fragments (#:~:text=...)
  url = url.replace(/#:~:text=[^#]*/, '');

  const hashIdx = url.indexOf('#');
  let fragment = hashIdx !== -1 ? url.slice(hashIdx) : '';
  if (hashIdx !== -1) url = url.slice(0, hashIdx);

  const qIdx = url.indexOf('?');
  let base = qIdx !== -1 ? url.slice(0, qIdx) : url;
  let query = qIdx !== -1 ? url.slice(qIdx + 1) : '';

  const TRACKING = new Set([
  'utm_source','utm_medium','utm_campaign','utm_term','utm_content','utm_id',
  'fbclid','gclid','msclkid','mc_eid','mc_cid',
  '_ga','_gl','twclid','igshid','s_kwcid','ef_id',
  'ck_subscriber_id'
]);

  if (query) {
    const filtered = query.split('&').filter(p => !TRACKING.has(p.split('=')[0]));
    query = filtered.length ? '?' + filtered.join('&') : '';
  }

  url = base + query + fragment;
}

return [{ json: { ...$input.first().json, url, hasUrl: url !== null } }];

const firecrawlResult = $('Firecrawl Scrape').first().json;
const firecrawlData = firecrawlResult.data || firecrawlResult;
const markdown = firecrawlData.markdown || '';
const title = firecrawlData.metadata?.title || 'Untitled';
const url = $('Extract URL').first().json.url;

// --- Fetch and decode the prompt template ---

const promptResult = $('Get Prompt Template').first();

if (promptResult.error || promptResult.json?.error) {
  const error = promptResult.error || promptResult.json.error;
  const message = typeof error === 'string' ? error : (error.message || JSON.stringify(error));
  throw new Error('Unable to fetch Templates/URL Interpreter Prompt.md: ' + message);
}

function decodeContent(item) {
  const json = item.json || {};
  if (typeof json.content === 'string') {
    try {
      return Buffer.from(json.content.replace(/\s/g, ''), 'base64').toString('utf8');
    } catch (error) {
      return json.content;
    }
  }
  if (typeof json.fileContent === 'string') return json.fileContent;
  if (typeof json.data === 'string') return json.data;
  return '';
}

const promptTemplate = decodeContent(promptResult);
if (!promptTemplate.trim()) {
  throw new Error('Templates/URL Interpreter Prompt.md is empty');
}

// --- Build topic list and matched topics section ---

const topicsItems = $('GitHub List Topics Capture').all();
const topicListError = topicsItems.find(item => item.json.error);
if (topicListError) {
  const error = topicListError.json.error;
  const message = typeof error === 'string' ? error : (error.message || JSON.stringify(error));
  throw new Error('Unable to list topics from GitHub: ' + message);
}

const existingTopics = topicsItems
  .map(item => item.json.name)
  .filter(name => name && name.endsWith('.md'))
  .map(name => name.replace(/\.md$/, ''))
  .sort();

const matchedTopicsSection = existingTopics.length > 0
  ? `## Matched Topics

From the following list of existing vault topic notes, identify any that this article is PRIMARILY ABOUT (not merely mentioned in passing or published by):

${existingTopics.join(', ')}

A topic only matches if the article would meaningfully contribute to that topic's note when synthesised. 
- An article about FAQ schema deprecation is ABOUT [[Schema Markup]] and [[Technical SEO]], not [[Google]] — Google is the actor, not the topic.
Format each matched topic as an Obsidian wikilink in double square brackets, comma-separated. For example: [[Digital PR]], [[Generative Engine Optimisation (GEO)]]. Be conservative. If no topic from the list applies, write "None" with no wikilinks.`
  : '';

// --- Substitute placeholders ---

const truncatedContent = markdown.length > 40000
  ? markdown.substring(0, 40000) + '\n\n[Content truncated]'
  : markdown;

const prompt = promptTemplate
  .replace('{MATCHED_TOPICS_SECTION}', matchedTopicsSection)
  .replace('{TITLE}', title)
  .replace('{URL}', url)
  .replace('{CONTENT}', truncatedContent);

return [{ json: { prompt, title, url } }];

const anthropicResponse = $input.first().json;
const body = anthropicResponse.text || '';
const promptData = $('Build Anthropic Prompt').first().json;
const title = promptData.title;
const url = promptData.url;
const firecrawlData = $('Firecrawl Scrape').first().json;
const firecrawlInner = firecrawlData.data || firecrawlData;
const fullText = firecrawlInner.markdown || '';


const now = new Date();
const isoTimestamp = now.toISOString();
const dateStr = isoTimestamp.split('T')[0];

const escapedTitle = title.replace(/"/g, '\\"');

const frontmatter = `---\ntitle: "${escapedTitle}"\ncreated: ${dateStr}\nsource: "${url}"\ntags:\nContentType: "Article"\ncaptured_via: "Telegram"\ncaptured_at: "${isoTimestamp}"\n---`;

const clipping = `${frontmatter}\n\n${body}\n\n---\n\n## Full Article\n\n${fullText}`;

return [{ json: { clipping, body, title, url, dateStr } }];

const { title, clipping, body, url, dateStr } = $input.first().json;

// Sanitise: strip / \ : * ? " < > |, collapse whitespace, trim to 100 chars
const sanitised = title
  .replace(/[\/\\:*?"<>|]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 100) || 'Untitled';

const filename = sanitised + '.md';
const path = 'Clippings/Telegram/' + filename;

return [{ json: { filename, path, clipping, body, title, url, dateStr } }];

const checkResult = $input.first();
const buildData = $('Build Filename').first().json;

// With onError: continueRegularOutput, a missing GitHub file appears as an error item.
// If there is no error, the title-derived path already exists and should not be captured again.
const fileExists = !checkResult.error && !checkResult.json?.error;

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

let filename = buildData.filename;
let path = buildData.path;
let duplicateArticle = false;
let duplicateReason = '';

if (fileExists) {
  duplicateArticle = true;
  duplicateReason = 'same filename already exists';
}

const commitMessage = 'Capture: ' + buildData.title;
const text = duplicateArticle
  ? [
      'Already captured',
      '',
      escapeHtml(buildData.title),
      '',
      'Matched on ' + escapeHtml(duplicateReason) + '.',
      '',
      'Vault path: <code>' + escapeHtml(buildData.path) + '</code>',
    ].join('\n')
  : '';

return [{ json: { filename, path, commitMessage, title: buildData.title, url: buildData.url, body: buildData.body, clipping: buildData.clipping, duplicateArticle, duplicateReason, chatId: $('Session Manager').first().json.chatId, text } }];

const resolveData = $('Resolve Filename').first().json;
const body = resolveData.body || '';
const title = resolveData.title;
const filename = resolveData.filename;
const chatId = $('Session Manager').first().json.chatId;

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Extract 'In summary,' sentence
const summaryMatch = body.match(/^In summary,\s*(.+)/m);
const summaryLine = summaryMatch ? ('In summary, ' + summaryMatch[1].trim()).substring(0, 220) : body.substring(0, 200);

// Extract Suggested Topics
const topicsMatch = body.match(/## Suggested Topics\s*\n+([^\n#]+)/);
const suggestedTopics = topicsMatch ? topicsMatch[1].trim() : 'See clipping';

const text = [
  'Captured',
  '',
  escapeHtml(title),
  '',
  escapeHtml(summaryLine),
  '',
  'Suggested topics: ' + escapeHtml(suggestedTopics),
  '',
  'Vault path: <code>Clippings/Telegram/' + escapeHtml(filename) + '</code>',
].join('\n');

return [{ json: { chatId, text } }];

const items = $input.all();
const chatId = $('Session Manager').first().json.chatId;

const errorItem = items.find(item => item.json.error);
if (errorItem) {
  const error = errorItem.json.error;
  const message = typeof error === 'string' ? error : (error.message || JSON.stringify(error));
  return [{ json: { chatId, text: 'Unable to list topics from GitHub: ' + message } }];
}

const topics = items
  .map(item => item.json.name)
  .filter(name => name && name.endsWith('.md'))
  .map(name => name.replace(/\.md$/, ''))
  .sort();

const text = topics.length === 0
  ? 'No topics yet...'
  : 'Available topics:\n' + topics.map(t => '- ' + t).join('\n');

return [{ json: { chatId, text } }];

const checkResult = $input.first();
const sourceIndexExists = !checkResult.error && !checkResult.json?.error;
const incoming = $('Extract URL').first().json;
const chatId = $('Session Manager').first().json.chatId;

function normaliseUrl(value) {
  if (!value) return '';
  try {
    const parsed = new URL(value.trim());
    parsed.hash = '';
    if (parsed.pathname !== '/') parsed.pathname = parsed.pathname.replace(/\/+$/, '');
    return parsed.toString();
  } catch (error) {
    return value.trim().replace(/\/+$/, '');
  }
}

async function readContent(item) {
  const json = item.json || {};

  if (item.binary?.data) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    return buffer.toString('utf8');
  }

  if (typeof json.fileContent === 'string') return json.fileContent;

  if (typeof json.content === 'string') {
    try {
      return Buffer.from(json.content.replace(/\s/g, ''), 'base64').toString('utf8');
    } catch (error) {
      return json.content;
    }
  }

  if (typeof json.data === 'string') return json.data;

  if (json.data && typeof json.data.content === 'string') {
    try {
      return Buffer.from(json.data.content.replace(/\s/g, ''), 'base64').toString('utf8');
    } catch (error) {
      return json.data.content;
    }
  }

  return '';
}

function parseSources(content) {
  if (!content.trim()) return {};
  try {
    const parsed = JSON.parse(content);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    throw new Error('Unable to parse Templates/sources.json: ' + error.message);
  }
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const sources = parseSources(await readContent.call(this, checkResult));
const normalisedUrl = normaliseUrl(incoming.url);
const existingPath = sources[normalisedUrl];
const duplicateArticle = Boolean(existingPath);

const text = duplicateArticle
  ? [
      'Already captured',
      '',
      escapeHtml(incoming.url),
      '',
      'Matched on source URL.',
      '',
      'Vault path: <code>' + escapeHtml(existingPath) + '</code>',
    ].join('\n')
  : '';

return [{
  json: {
    ...incoming,
    chatId,
    sourceIndexExists,
    sources,
    normalisedUrl,
    duplicateArticle,
    duplicateReason: duplicateArticle ? 'same source URL' : '',
    path: existingPath || '',
    text,
  },
}];

const resolveData = $('Resolve Filename').first().json;
const sourceIndexData = $('Check Source Index').first().json;
const sources = sourceIndexData.sources && typeof sourceIndexData.sources === 'object' ? sourceIndexData.sources : {};
sources[sourceIndexData.normalisedUrl] = resolveData.path;

const sourceIndexContent = JSON.stringify(sources, Object.keys(sources).sort(), 2) + '\n';
const commitMessage = 'Update source index: ' + resolveData.title;

return [{ json: { ...resolveData, sourceIndexExists: sourceIndexData.sourceIndexExists, sourceIndexPath: '.code/sources.json', sourceIndexContent, commitMessage } }];

const data = $('Resolve Filename').first().json;
const entry = {
  timestamp: new Date().toISOString(),
  chat_id: data.chatId,
  url: data.url,
  status: 'success',
  vault_path: data.path
};
return [{ json: { logEntry: JSON.stringify(entry) + '\n', logFileExists: false, sha: undefined } }];

const logEntry = $('Build Capture Log Entry').first().json.logEntry;
const getResult = $input.first();
const fileExists = !getResult.error && !getResult.json?.error;

let existingContent = '';
let sha = undefined;

if (fileExists) {
  const json = getResult.json || {};
  sha = json.sha || json.data?.sha;

  function decodeContent(j) {
    if (typeof j.content === 'string') {
      try { return Buffer.from(j.content.replace(/\s/g, ''), 'base64').toString('utf8'); } catch(e) { return j.content; }
    }
    if (typeof j.fileContent === 'string') return j.fileContent;
    if (typeof j.data === 'string') return j.data;
    if (j.data && typeof j.data.content === 'string') {
      try { return Buffer.from(j.data.content.replace(/\s/g, ''), 'base64').toString('utf8'); } catch(e) { return j.data.content; }
    }
    return '';
  }

  existingContent = decodeContent(json);
}

const NL = String.fromCharCode(10);
const trimmed = existingContent.trimEnd();
const newContent = trimmed ? trimmed + NL + logEntry : logEntry;
return [{ json: { newContent, sha, fileExists } }];
